    const contracts = options.contracts !== undefined
        ? parseExchangeContracts(options.contracts)
        : getDefaultExchangeChainConfig(chainId)?.contracts;
    const depositLedger = options.depositLedger ?? contracts?.depositLedger;
    if (depositLedger === undefined) {
        throw createProtocolValidationError("missing_field", "$.depositLedger", "depositLedger is required when no default depositLedger exists for chainId");
